#pragma once
#include <Arduino.h>
#include "BoardConfig.h"

// PWM is generated by LEDC hardware even while CAN frames are being received.
class ServoOutput {
 public:
  void off() {
    for (uint8_t i = 0; i < 15; ++i) {
      if (attached_[i]) ledcDetach(hand_config::kPins[i]);
      attached_[i] = false;
      pinMode(hand_config::kPins[i], OUTPUT);
      digitalWrite(hand_config::kPins[i], LOW);
    }
  }

  bool apply(const uint16_t pose[15]) {
    // Called only after a complete set has passed every motor's range check.
    // Attach once on first output, then update duty without restarting timers.
    for (uint8_t i = 0; i < 15; ++i) {
      if (!attached_[i]) {
        if (!ledcAttachChannel(hand_config::kPins[i], 50, 16, i)) {
          off();
          return false;
        }
        attached_[i] = true;
      }
    }
    for (uint8_t i = 0; i < 15; ++i) {
      const uint32_t duty = (static_cast<uint32_t>(pose[i]) * 65536U + 10000U) / 20000U;
      if (!ledcWrite(hand_config::kPins[i], duty)) {
        off();
        return false;
      }
    }
    for (uint8_t i = 0; i < 15; ++i) lastCommandUs_[i] = pose[i];
    return true;
  }

 private:
  bool attached_[15] = {};
  uint16_t lastCommandUs_[15] = {};  // command history, never a measured position
};
